                var quotas = [decisions.quotaBogNorte, decisions.quotaBogSur, decisions.quotaCosta, decisions.quotaEje];
                for (var q = 0; q < quotas.length; q++) {
                    if (quotas[q] < 80 || quotas[q] > 120) {
                        window.mySimulation.uiManager.showNotification(
                            window.mySimulation.t('quota_range_warning'), 'warning'
                        );
                        return false;
                    }
                }

                var cp = document.getElementById('compPlan');
                if (cp) decisions.compPlan = parseInt(cp.value) || 4;

                var tp = document.getElementById('trainProduct');
                var tc = document.getElementById('trainConsultative');
                var tr = document.getElementById('trainCRM');
                var tl = document.getElementById('trainClinical');
                if (tp) decisions.trainProduct = parseInt(tp.value) || 0;
                if (tc) decisions.trainConsultative = parseInt(tc.value) || 0;
                if (tr) decisions.trainCRM = parseInt(tr.value) || 0;
                if (tl) decisions.trainClinical = parseInt(tl.value) || 0;

                var trainSum = decisions.trainProduct + decisions.trainConsultative + decisions.trainCRM + decisions.trainClinical;
                if (trainSum > 400) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('training_sum_warning'), 'warning'
                    );
                    return false;
                }

                var hc = document.getElementById('hunterCount');
                if (hc) decisions.hunterCount = parseInt(hc.value) || 4;
                if (decisions.hunterCount < 2 || decisions.hunterCount > 8) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('hunter_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var ad = document.getElementById('andresDecision');
                var cd = document.getElementById('costaDecision');
                var kd = document.getElementById('kamDecision');
                var cpd = document.getElementById('complianceDecision');
                var dd = document.getElementById('digitalDecision');
                if (ad) decisions.andresDecision = parseInt(ad.value) || 1;
                if (cd) decisions.costaDecision = parseInt(cd.value) || 1;
                if (kd) decisions.kamDecision = parseInt(kd.value) || 1;
                if (cpd) decisions.complianceDecision = parseInt(cpd.value) || 1;
                if (dd) decisions.digitalDecision = parseInt(dd.value) || 1;
            } else if (period === 3) {
                var at = document.getElementById('aTierCount');
                var kr = document.getElementById('kamReps');
                var qr = document.getElementById('quotaResetStrategy');
                var pr = document.getElementById('poachResponse');
                if (at) decisions.aTierCount = parseInt(at.value) || 12;
                if (kr) decisions.kamReps = parseInt(kr.value) || 2;
                if (qr) decisions.quotaResetStrategy = parseInt(qr.value) || 1;
                if (pr) decisions.poachResponse = parseInt(pr.value) || 1;

                if (decisions.aTierCount < 5 || decisions.aTierCount > 20) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('a_tier_warning'), 'warning'
                    );
                    return false;
                }
                if (decisions.kamReps < 1 || decisions.kamReps > 4) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('kam_reps_warning'), 'warning'
                    );
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        _quotaMotivation(quotaPct) {
            if (quotaPct >= 95 && quotaPct <= 105) return 0.96;
            if (quotaPct >= 90 && quotaPct < 95) return 0.89;
            if (quotaPct >= 80 && quotaPct < 90) return 0.82;
            if (quotaPct > 105 && quotaPct <= 110) return 0.87;
            if (quotaPct > 110 && quotaPct <= 115) return 0.76;
            return 0.65;
        }

        _roundPotential() {
            var p = this.TERRITORY_POTENTIAL;
            return (p.bogotaNorte + p.bogotaSur + p.costa + p.ejeCafetero) / 4;
        }

        _coverageFactor(reps, ideal) {
            var ratio = reps / ideal;
            if (ratio <= 1) return 0.70 + 0.30 * ratio;
            return 1.0 + 0.08 * Math.log(ratio);
        }

        _rollEvent(round) {
            var roll = window.mySimulation.adapter._rng() * 100;
            if (round === 1) {
                if (roll < 40) return 'event_procurement';
            } else if (round === 2) {
                if (roll < 30) return 'event_liquidation';
                if (roll < 55) return 'event_medsupply_recruit';
            } else if (round === 3) {
                if (roll < 60) return 'event_insurance_expansion';
            }
            return '';
        }

        _seedRng(seed) { this._rngState = ((seed >>> 0) || 1) >>> 0; }
        _rng() {
            this._rngState = (this._rngState + 0x6D2B79F5) >>> 0;
            var t = this._rngState;
            t = Math.imul(t ^ (t >>> 15), t | 1) >>> 0;
            t = (t ^ (t + Math.imul(t ^ (t >>> 7), t | 61))) >>> 0;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        }
        _hashSeed(period, gameId) {
            /* 1.2.0: the draws come from the game and the round only, never from the decision values, so an
               inert input can no longer redraw every event (TN-Exhibit 7); undo and reload still replay exactly */
            var s = 'p' + period + '|g=' + (gameId == null ? '' : String(gameId));
            var h = 2166136261 >>> 0;
            for (var c = 0; c < s.length; c++) { h = Math.imul(h ^ s.charCodeAt(c), 16777619) >>> 0; }
            return h >>> 0;
        }
        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            this._seedRng(this._hashSeed(period, state.gameId));
            var event = this._rollEvent(period);
            ds.activeEvent = event;

            var roundRevenue = 0;
            var roundQuota = 0;
            var roundExits = 0;
            var roundNewAccounts = 0;
            var pipelineDelta = 0;
            var complianceDelta = 0;

            if (period === 1) {
                ds.territories.bogotaNorte = { reps: d.repsBogNorte, quota: d.quotaBogNorte };
                ds.territories.bogotaSur = { reps: d.repsBogSur, quota: d.quotaBogSur };
                ds.territories.costa = { reps: d.repsCosta, quota: d.quotaCosta };
                ds.territories.ejeCafetero = { reps: d.repsEje, quota: d.quotaEje };
                ds.compPlan = d.compPlan;
                ds.hunterCount = d.hunterCount;

                var trainTotal = d.trainProduct + d.trainConsultative + d.trainCRM + d.trainClinical;
                ds.trainingLevel = trainTotal;
                ds.skillFactor = 0.85 + (trainTotal / 400) * 0.10;

                var compMult = this.COMP_MULTIPLIER[d.compPlan] || 1.0;
                var territories = ['bogotaNorte', 'bogotaSur', 'costa', 'ejeCafetero'];
                var self = this;

                territories.forEach(function(t) {
                    var pot = self.TERRITORY_POTENTIAL[t];
                    var ideal = self.IDEAL_REPS[t];
                    var reps = ds.territories[t].reps;
                    var quotaPct = ds.territories[t].quota;

                    var coverage = self._coverageFactor(reps, ideal);
                    var motivation = self._quotaMotivation(quotaPct);
                    var noise = 0.96 + window.mySimulation.adapter._rng() * 0.08;

                    var costaDebuff = (t === 'costa') ? 0.82 : 1.0;
                    var annualRev = pot * coverage * motivation * compMult * ds.skillFactor * costaDebuff * noise;
                    var quarterRev = annualRev / 4;

                    roundRevenue += quarterRev;
                    roundQuota += (pot * quotaPct / 100) / 4;
                });

                var baseTurnover = this.COMP_TURNOVER[d.compPlan] || 0.14;
                var avgQuota = (d.quotaBogNorte + d.quotaBogSur + d.quotaCosta + d.quotaEje) / 4;
                ds.round1QuotaAvg = avgQuota;
                var quotaPenalty = Math.abs(avgQuota - 100) * 0.003;
                var turnoverProb = baseTurnover + quotaPenalty - (trainTotal / 400) * 0.05;
                roundExits = Math.round(24 * Math.max(0, Math.min(turnoverProb, 0.35)));

                roundNewAccounts = Math.round(d.hunterCount * (1.5 + window.mySimulation.adapter._rng() * 1.5));
                pipelineDelta = (d.hunterCount - 4) * 3 + (d.trainConsultative / 50) * 2 + roundNewAccounts * 0.5 - 5;

                if (event === 'event_procurement') {
                    roundRevenue *= 0.88;
                    pipelineDelta -= 8;
                }

            } else if (period === 2) {
                var compMult2 = this.COMP_MULTIPLIER[ds.compPlan] || 1.0;
                var territories2 = ['bogotaNorte', 'bogotaSur', 'costa', 'ejeCafetero'];
                var self2 = this;

                /* 1.2.0: an individual match is a precedent the other reps see (case, Option B and the 2022 history; TN Q3) */
                ds.offersMatched = (d.andresDecision === 1) ? 1 : 0;
                if (d.andresDecision === 1) {
                    ds.andresRetained = true;
                } else if (d.andresDecision === 2) {
                    ds.andresRetained = window.mySimulation.adapter._rng() > 0.2;
                } else {
                    ds.andresRetained = window.mySimulation.adapter._rng() > 0.6;
                }

                var costaBoost = 1.0;
                if (d.costaDecision === 1) {
                    costaBoost = 1.10;
                    ds.costaFixed = true;
                } else if (d.costaDecision === 2) {
                    costaBoost = 0.85;
                    roundExits += 2;
                } else {
                    costaBoost = 1.18;
                    ds.costaFixed = true;
                }

                var kamRevBonus = 0;
                if (d.kamDecision === 1) {
                    kamRevBonus = 320 + window.mySimulation.adapter._rng() * 180;
                } else if (d.kamDecision === 2) {
                    kamRevBonus = 80 + window.mySimulation.adapter._rng() * 120;
                } else {
                    kamRevBonus = 220 + window.mySimulation.adapter._rng() * 160;
                }

                territories2.forEach(function(t) {
                    var pot = self2.TERRITORY_POTENTIAL[t];
                    var reps = ds.territories[t].reps;
                    var ideal = self2.IDEAL_REPS[t];
                    var quotaPct = ds.territories[t].quota;
                    var coverage = self2._coverageFactor(reps, ideal);
                    var motivation = self2._quotaMotivation(quotaPct);
                    var noise = 0.965 + window.mySimulation.adapter._rng() * 0.07;
                    var costaAdj = (t === 'costa') ? costaBoost * 0.82 : 1.0;
                    var annualRev = pot * coverage * motivation * compMult2 * ds.skillFactor * costaAdj * noise;
                    var quarterRev = annualRev / 4;
                    roundRevenue += quarterRev;
                    roundQuota += (pot * ds.territories[t].quota / 100) / 4;
                });

                roundRevenue += kamRevBonus;

                if (!ds.andresRetained) {
                    roundRevenue *= 0.93;
                    roundExits += 1;
                }

                if (d.complianceDecision === 1) {
                    complianceDelta = -5;
                } else if (d.complianceDecision === 2) {
                    complianceDelta = 5;
                } else {
                    complianceDelta = 15;
                    roundExits += 2;
                }

                if (d.digitalDecision === 1) {
                    ds.hasPortal = true;
                    pipelineDelta += 10;
                    roundNewAccounts += 3;
                } else {
                    pipelineDelta += 5;
                    roundNewAccounts += 1;
                }

                roundNewAccounts += Math.round(2 + window.mySimulation.adapter._rng() * 3);

                if (event === 'event_liquidation') {
                    roundRevenue *= 0.90;
                    roundNewAccounts = Math.max(0, roundNewAccounts - 3);
                } else if (event === 'event_medsupply_recruit') {
                    roundRevenue *= 1.04;
                    roundNewAccounts += 3;
                    pipelineDelta += 5;
                }

            } else if (period === 3) {
                var compMult3 = this.COMP_MULTIPLIER[ds.compPlan] || 1.0;
                var territories3 = ['bogotaNorte', 'bogotaSur', 'costa', 'ejeCafetero'];
                var self3 = this;

                var kamCovPenalty = d.kamReps * 0.02;
                var kamRevMult = 1.0 + (d.aTierCount / 340) * 0.5 * (d.kamReps / 2);

                var ratchetPenalty = 1.0;
                if (d.quotaResetStrategy === 3) {
                    ds.ratchetTriggered = true;
                    ratchetPenalty = 0.85;
                } else if (d.quotaResetStrategy === 2) {
                    ratchetPenalty = 0.95;
                } else {
                    ratchetPenalty = 1.02;
                }

                /* 1.2.0: each individual match (Reyes in round 2, all three now) tells the team and MedSupply the price:
                   pay compression lowers the effort of the reps who were not matched, and MedSupply comes back for the next rep */
                var precedent = (ds.offersMatched || 0) + (d.poachResponse === 1 ? 1 : 0);
                var compression = 1 - 0.05 * precedent;
                /* 1.2.0: the reset is announced now; a next-year quota above the 105 percent sweet spot pushes reps out,
                   with the same 0.003 per point the round 1 quota turnover uses */
                var resetUplift = d.quotaResetStrategy === 3 ? 1.175 : (d.quotaResetStrategy === 2 ? 1.075 : 1.0);
                ds.nextYearQuota = Math.round((ds.round1QuotaAvg || 100) * resetUplift);
                var ratchetExits = Math.round(24 * 0.003 * Math.max(0, ds.nextYearQuota - 105));
                territories3.forEach(function(t) {
                    var pot = self3.TERRITORY_POTENTIAL[t];
                    var reps = ds.territories[t].reps;
                    var ideal = self3.IDEAL_REPS[t];
                    var quotaPct = ds.territories[t].quota;
                    var coverage = self3._coverageFactor(reps, ideal) - kamCovPenalty;
                    var motivation = self3._quotaMotivation(quotaPct) * ratchetPenalty * compression;
                    var noise = 0.965 + window.mySimulation.adapter._rng() * 0.07;
                    var costaAdj = (t === 'costa' && ds.costaFixed) ? 0.95 : (t === 'costa' ? 0.78 : 1.0);
                    var annualRev = pot * coverage * motivation * compMult3 * ds.skillFactor * costaAdj * noise;
                    var quarterRev = annualRev / 4;
                    roundRevenue += quarterRev;
                    roundQuota += (pot * quotaPct / 100) / 4;
                });

                roundRevenue *= kamRevMult;

                var poachExits = 0;
                if (d.poachResponse === 1) {
                    poachExits = 0;
                    roundRevenue *= 0.97;
                } else if (d.poachResponse === 2) {
                    poachExits = window.mySimulation.adapter._rng() > 0.7 ? 1 : 0;
                } else {
                    poachExits = 2 + (window.mySimulation.adapter._rng() > 0.5 ? 1 : 0);
                    roundRevenue *= 0.91;
                }
                roundExits += poachExits + precedent + ratchetExits;
                ds.precedentExits = precedent;
                ds.ratchetExits = ratchetExits;

                if (ds.hasPortal) {
                    roundNewAccounts += 4;
                    pipelineDelta += 6;
                }

                roundNewAccounts += Math.round(ds.hunterCount * (1.0 + window.mySimulation.adapter._rng()));

                if (event === 'event_insurance_expansion') {
                    roundRevenue *= 1.12;
                    roundNewAccounts += 5;
                    pipelineDelta += 10;
                }
            }

            roundRevenue = Math.round(roundRevenue);
            ds.totalRevenue += roundRevenue;
            ds.cumulativeQuota += Math.round(roundQuota);
            ds.repsRemaining = Math.max(10, ds.repsRemaining - roundExits);
            ds.voluntaryExits += roundExits;
            ds.newAccounts += roundNewAccounts;
            ds.pipelineHealth = Math.max(20, Math.min(100, ds.pipelineHealth + pipelineDelta));
            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + complianceDelta));

            var quotaAtt = ds.cumulativeQuota > 0 ? Math.round((ds.totalRevenue / ds.cumulativeQuota) * 100) : 0;
            var retentionRate = Math.round((ds.repsRemaining / 24) * 100);
            var turnoverAnnual = Math.round((ds.voluntaryExits / 24) * 100);

            /* 1.2.0: revenue is scored against the market potential of the round (adjusted for market events),
               not against the quota the student set, so an easy quota no longer buys points (TN 12.2).
               Zero credit at the 76 percent the firm makes today, full credit at the 94 percent plan (case abstract). */
            var marketFactor = event === 'event_procurement' ? 0.88 : event === 'event_liquidation' ? 0.90 : event === 'event_insurance_expansion' ? 1.12 : 1.0;
            ds.cumulativePotential = (ds.cumulativePotential || 0) + Math.round(this._roundPotential() * marketFactor);
            ds.revenueIndex = ds.cumulativePotential > 0 ? Math.round(1000 * ds.totalRevenue / ds.cumulativePotential) / 10 : 0;
            var revenueScore = Math.round(350 * Math.max(0, Math.min(1, (ds.revenueIndex - 76) / (94 - 76))));
            var retentionScore = turnoverAnnual <= 15 ? 250 : Math.max(0, 250 - (turnoverAnnual - 15) * 12);
            var pipelineScore = Math.round((ds.pipelineHealth / 100) * 200);
            var newAcctScore = Math.min(100, Math.round((ds.newAccounts / (8 * period)) * 100));
            var compScore = Math.round((ds.complianceScore / 100) * 100);
            var totalScore = revenueScore + retentionScore + pipelineScore + newAcctScore + compScore;
            ds.scoreParts = { revenue: revenueScore, retention: retentionScore, pipeline: pipelineScore, accounts: newAcctScore, compliance: compScore };

            ds.revenueHistory.push(roundRevenue);
            ds.quotaAttHistory.push(quotaAtt);
            ds.retentionHistory.push(ds.repsRemaining);
            ds.pipelineHistory.push(ds.pipelineHealth);
            ds.complianceHistory.push(ds.complianceScore);
            ds.scoreHistory.push(totalScore);
            ds.newAccountHistory.push(roundNewAccounts);

            // overallScore scales totalScore (0-1000, the same composite getPerformanceSummary reads as its final totalScore verdict metric) down to 0-100
            var overallScore = Math.max(0, Math.min(100, Math.round(100 * totalScore / 1000)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var results = {
                period: period,
                revenue: roundRevenue,
                quotaTarget: Math.round(roundQuota),
                quotaAttainment: quotaAtt,
                repsRemaining: ds.repsRemaining,
                exits: roundExits,
                pipelineHealth: ds.pipelineHealth,
                complianceScore: ds.complianceScore,
                newAccounts: roundNewAccounts,
                score: totalScore,
                event: event
            };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                (v) => 'COP ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('quotaAttDisplay', 'results.quotaAttainment',
                (v) => v + '%');
            uiManager.bind('retentionDisplay', 'domainState.repsRemaining',
                (v) => v + '/24');
            uiManager.bind('pipelineDisplay', 'domainState.pipelineHealth',
                (v) => Math.round(v));
            uiManager.bind('complianceDisplay', 'domainState.complianceScore',
                (v) => Math.round(v));
            uiManager.bind('scoreDisplay', 'results.score',
                (v) => Math.round(v));
        }

        getChartConfig() {
            return {
                revenueChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Revenue (COP M)',
                            data: [],
                            backgroundColor: 'rgba(46,134,193,0.7)',
                            borderColor: '#2e86c1',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Revenue per Round' } },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Composite Score',
                            data: [],
                            borderColor: '#f39c12',
                            backgroundColor: 'rgba(243,156,18,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Score Over Rounds' } },
                        scales: { y: { beginAtZero: true, max: 1000 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                revenueChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.revenueHistory }]
                },
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        _tr(key, vals) {
            var txt = window.mySimulation ? window.mySimulation.t(key) : key;
            Object.keys(vals || {}).forEach(function(k) { txt = txt.split('{' + k + '}').join(String(vals[k])); });
            return txt;
        }

        _tierOf(totalScore) {
            /* 1.2.0: bands derived from the calibration sweep: excellent from the expert play p10, strong from the random p90 */
            if (totalScore >= 880) return 'excellent';
            if (totalScore >= 650) return 'strong';
            if (totalScore >= 450) return 'developing';
            return 'needs';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var last = history[history.length - 1] || {};
            var lastResult = last.results || {};
            var ds = last.domainState || (window.mySimulation ? window.mySimulation.state.domainState : {}) || {};
            var totalScore = lastResult.score || 0;
            var totalRevenue = 0;
            var totalNewAccounts = 0;
            history.forEach(function(h) {
                totalRevenue += (h.results && h.results.revenue) || 0;
                totalNewAccounts += (h.results && h.results.newAccounts) || 0;
            });
            var d1 = (history[0] && history[0].decisions) || {};
            var d2 = (history[1] && history[1].decisions) || null;
            var d3 = (history[2] && history[2].decisions) || null;
            var q = Math.round(((d1.quotaBogNorte || 100) + (d1.quotaBogSur || 100) + (d1.quotaCosta || 100) + (d1.quotaEje || 100)) / 4);
            var rIdx = ds.revenueIndex != null ? Math.round(ds.revenueIndex) : null;
            var att = lastResult.quotaAttainment;
            var exits = ds.voluntaryExits || 0;

            var tier = this._tierOf(totalScore);
            var insights = [];
            var turning = [];
            /* the mistake map of this sim, detected from the run: teacher-facing names stay in the teaching block */
            if (q > 105) {
                insights.push(this._tr('ins_quota_stretch', { q: q, r: rIdx }));
                turning.push({ round: 1, key: 'tp_quota_stretch' });
            } else if (q < 95) {
                insights.push(this._tr('ins_quota_easy', { q: q, a: att, r: rIdx }));
                turning.push({ round: 1, key: 'tp_quota_easy' });
            } else {
                insights.push(this._tr('ins_quota_ok', { q: q, r: rIdx }));
            }
            if (d2) {
                if (d2.costaDecision === 2) {
                    insights.push(this._tr('ins_costa_replace', {}));
                    turning.push({ round: 2, key: 'tp_costa_replace' });
                } else {
                    insights.push(this._tr(d2.costaDecision === 3 ? 'ins_costa_coach' : 'ins_costa_pip', {}));
                }
            }
            var matched = (d2 && d2.andresDecision === 1 ? 1 : 0) + (d3 && d3.poachResponse === 1 ? 1 : 0);
            if (matched > 0) {
                insights.push(this._tr('ins_match', { n: matched, x: ds.precedentExits || matched }));
                turning.push({ round: (d2 && d2.andresDecision === 1) ? 2 : 3, key: 'tp_match' });
            } else if (d3 && d3.poachResponse === 3) {
                insights.push(this._tr('ins_poach_accept', {}));
                turning.push({ round: 3, key: 'tp_poach_accept' });
            } else if (d3) {
                insights.push(this._tr('ins_poach_team', {}));
            }
            if (d3) {
                if (d3.quotaResetStrategy === 3) {
                    insights.push(this._tr('ins_reset_ratchet', { nq: ds.nextYearQuota || '', x: ds.ratchetExits || 0 }));
                    turning.push({ round: 3, key: 'tp_reset_ratchet' });
                } else if (d3.quotaResetStrategy === 2) {
                    insights.push(this._tr('ins_reset_moderate', { nq: ds.nextYearQuota || '' }));
                } else {
                    insights.push(this._tr('ins_reset_flat', {}));
                }
            }
            insights.push(this._tr(exits * 100 / 24 <= 15 ? 'ins_turnover_ok' : 'ins_turnover_high', { x: exits, t: Math.round(exits * 100 / 24) }));

            var tp = turning.length ? this._tr('tp_round', { n: turning[0].round }) + ' ' + this._tr(turning[0].key, {}) : this._tr('tp_none', {});
            return {
                totalScore: totalScore,
                overallScore: Math.max(0, Math.min(100, Math.round(totalScore / 10))),
                totalRevenue: totalRevenue,
                totalNewAccounts: totalNewAccounts,
                revenueIndex: rIdx,
                quotaAttainment: att,
                repsRemaining: lastResult.repsRemaining,
                pipelineHealth: lastResult.pipelineHealth,
                complianceScore: lastResult.complianceScore,
                scoreParts: ds.scoreParts || null,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._tr('tier_' + tier, {}),
                turningPoint: tp,
                insights: insights,
                questions: [this._tr('dq_1', {}), this._tr('dq_2', {}), this._tr('dq_3', {})]
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var e = function(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var kpi = function(labelKey, val) {
                return '<div class="indumed-sim-cm-kpi"><span class="indumed-sim-cm-kpi-l">' + e(self._tr(labelKey, {})) + '</span><strong>' + e(val) + '</strong></div>';
            };
            var parts = summary.scoreParts || {};
            var partRow = function(k, max) { return '<li>' + e(self._tr('part_' + k, {})) + ': <strong>' + e(parts[k] != null ? parts[k] : 0) + '</strong> / ' + max + '</li>'; };
            var html = '<div class="indumed-sim-cm" role="region" aria-label="' + e(this._tr('cm_title', {})) + '">';
            html += '<h3 class="indumed-sim-cm-h">' + e(this._tr('cm_title', {})) + '</h3>';
            html += '<p class="indumed-sim-cm-score"><strong>' + e(summary.overallScore) + '</strong> / 100 · ' + e(summary.performanceLabel) + '</p>';
            html += '<div class="indumed-sim-cm-kpis">' + kpi('cm_rev_index', (summary.revenueIndex != null ? summary.revenueIndex : '-') + '%') + kpi('quota_att_label', (summary.quotaAttainment != null ? summary.quotaAttainment : '-') + '%') +
                kpi('retention_label', (summary.repsRemaining != null ? summary.repsRemaining : '-') + '/24') + kpi('pipeline_label', summary.pipelineHealth != null ? Math.round(summary.pipelineHealth) : '-') +
                kpi('compliance_label', summary.complianceScore != null ? Math.round(summary.complianceScore) : '-') + '</div>';
            html += '<h4 class="indumed-sim-cm-h4">' + e(this._tr('cm_turning', {})) + '</h4><p>' + e(summary.turningPoint) + '</p>';
            html += '<h4 class="indumed-sim-cm-h4">' + e(this._tr('cm_insights', {})) + '</h4><ul>' + (summary.insights || []).map(function(t) { return '<li>' + e(t) + '</li>'; }).join('') + '</ul>';
            html += '<h4 class="indumed-sim-cm-h4">' + e(this._tr('cm_parts', {})) + '</h4><ul>' + partRow('revenue', 350) + partRow('retention', 250) + partRow('pipeline', 200) + partRow('accounts', 100) + partRow('compliance', 100) + '</ul>';
            html += '<h4 class="indumed-sim-cm-h4">' + e(this._tr('cm_questions', {})) + '</h4><ol>' + (summary.questions || []).map(function(t) { return '<li>' + e(t) + '</li>'; }).join('') + '</ol>';
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.exits >= 3) return window.mySimulation.t('hint_high_turnover');
            if (results.pipelineHealth < 50) return window.mySimulation.t('hint_pipeline_weak');
            if (results.complianceScore < 70) return window.mySimulation.t('hint_compliance_risk');
            /* 1.2.0: praise revenue against potential, not attainment against a quota the student may have set low */
            var rIdx = state && state.domainState ? state.domainState.revenueIndex : null;
            if (rIdx != null && rIdx >= 90 && results.repsRemaining >= 22) return window.mySimulation.t('hint_excellent');
            if (results.quotaAttainment < 80) return window.mySimulation.t('hint_low_quota');
            return null;
        }

